16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.util.*;
25	
26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	public class Owner extends Person {
37	    @Column(name = "address")
38	    @NotEmpty
39	    private String address;
40	
41	    @Column(name = "city")
42	    @NotEmpty
43	    private String city;
44	
45	    @Column(name = "telephone")
46	    @NotEmpty
47	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: '+' followed by 8 to 15 digits")
48	    private String telephone;
49	
50	    @Column(name = "email")
51	    private String email;
52	
53	    @Column(name = "registration_date", columnDefinition = "DATE")
54	    private java.time.LocalDate registrationDate;
55	
56	    @Column(name = "customer_code")
57	    private String customerCode;
58	
59	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
60	    private Set<Pet> pets;
61	
62	    public String getAddress() {
63	        return this.address;
64	    }
65	
66	    public void setAddress(String address) {
67	        this.address = address;
68	    }
69	
70	    public String getCity() {
71	        return this.city;
72	    }
73	
74	    public void setCity(String city) {
75	        this.city = city;
76	    }
77	
78	    public String getTelephone() {
79	        return this.telephone;
80	    }
81	
82	    public void setTelephone(String telephone) {
83	        this.telephone = telephone;
84	    }
85	
86	    public String getEmail() {
87	        return this.email;
88	    }
89	
90	    public void setEmail(String email) {
91	        this.email = email;
92	    }
93	
94	    public java.time.LocalDate getRegistrationDate() {
95	        return this.registrationDate;
96	    }
97	
98	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
99	        this.registrationDate = registrationDate;
100	    }
101	
102	    public String getCustomerCode() {
103	        return this.customerCode;
104	    }
105	
106	    public void setCustomerCode(String customerCode) {
107	        this.customerCode = customerCode;
108	    }
109	
110	    protected Set<Pet> getPetsInternal() {
111	        if (this.pets == null) {
112	            this.pets = new HashSet<>();
113	        }
114	        return this.pets;
115	    }
116	
117	    protected void setPetsInternal(Set<Pet> pets) {
118	        this.pets = pets;
119	    }
120	
121	    public List<Pet> getPets() {
122	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
123	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
124	        return Collections.unmodifiableList(sortedPets);
125	    }
126	
127	    public void setPets(List<Pet> pets) {
128	        this.pets = new HashSet<>(pets);
129	    }
130	
131	    public void addPet(Pet pet) {
132	        getPetsInternal().add(pet);
133	        pet.setOwner(this);
134	    }
135	
136	    /**
137	     * Return the Pet with the given name, or null if none found for this Owner.
138	     *
139	     * @param name to test
140	     * @return true if pet name is already in use
141	     */
142	    public Pet getPet(String name) {
143	        return getPet(name, false);
144	    }
145	
146	    /**
147	     * Return the Pet with the given name, or null if none found for this Owner.
148	     *
149	     * @param name to test
150	     * @return true if pet name is already in use
151	     */
152	    public Pet getPet(String name, boolean ignoreNew) {
153	        name = name.toLowerCase();
154	        for (Pet pet : getPetsInternal()) {
155	            if (!ignoreNew || !pet.isNew()) {
156	                String compName = pet.getName();
157	                compName = compName.toLowerCase();
158	                if (compName.equals(name)) {
159	                    return pet;
160	                }
161	            }
162	        }
163	        return null;
164	    }
165	
166	    public Pet getPet(Integer petId) {
167	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
168	    }
169	
170	    @Override
171	    public String toString() {
172	        return new ToStringCreator(this)
173	
174	            .append("id", this.getId())
175	            .append("new", this.isNew())
176	            .append("lastName", this.getLastName())
177	            .append("firstName", this.getFirstName())
178	            .append("address", this.address)
179	            .append("city", this.city)
180	            .append("telephone", this.telephone)
181	            .toString();
182	    }
183	}
