44	        if (!missing.isEmpty()) {
45	            throw new MissingOwnerFieldsException(missing);
46	        }
47	        request.setTelephone(TelephoneNormalizer.normalize(request.getTelephone()));
48	        request.setEmail(normalizeEmail(request.getEmail()));
49	        Owner owner = ownerMapper.toOwner(request);
50	        if (owner.getRegistrationDate() == null) {
51	            owner.setRegistrationDate(java.time.LocalDate.now());
52	        }
53	        owner.setCustomerCode(nextCustomerCode(owner.getLastName(), ownerRepository));
54	        built.set(owner);
55	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
56	    }
57	
58	    /**
59	     * Build a customer code '<LAST3>-<NNNN>': the upper-cased first three letters of the last
60	     * name, a hyphen, then a global 4-digit zero-padded sequence equal to one more than the
61	     * current number of owners (e.g. 'SMI-0007').
62	     */
63	    private static String nextCustomerCode(String lastName, OwnerRepository ownerRepository) {
64	        String last3 = lastName.substring(0, Math.min(3, lastName.length()))
65	                .toUpperCase(java.util.Locale.ROOT);
66	        int sequence = ownerRepository.findAll().size() + 1;
67	        return String.format("%s-%04d", last3, sequence);
68	    }
69	
70	    /** When present, require a syntactically valid address and store it lower-cased; else reject with 400. */
71	    private static String normalizeEmail(String email) throws InvalidEmailException {
72	        if (email == null || email.isBlank()) {
73	            return null;
74	        }
75	        String trimmed = email.trim();
76	        if (!EMAIL.matcher(trimmed).matches()) {
77	            throw new InvalidEmailException(email);
78	        }
79	        return trimmed.toLowerCase(java.util.Locale.ROOT);
80	    }
81	
82	    private static boolean isBlank(String value) {
83	        return value == null || value.isBlank();
84	    }
85	}
