24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
26	                continue; // same record (e.g. re-save), not a conflict
27	            }
28	            if (lastName.equals(key(existing.getLastName()))
29	                    && address.equals(key(existing.getAddress()))) {
30	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
31	            }
32	        }
33	    }
34	
35	    /** Comparison key: lower-cased, with leading/trailing and repeated whitespace collapsed. */
36	    private static String key(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
41	    }
42	}
