1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
4	
5	/**
6	 * Single home for owner telephone normalization. Both the create pipeline's
7	 * {@link BuildOwner} (which stores the canonical form) and
8	 * {@link CheckOwnerTelephoneUnique} (which detects duplicates) go through here, so the
9	 * stored form and the duplicate-comparison stay defined in one place.
10	 */
11	final class TelephoneNormalizer {
12	
13	    private TelephoneNormalizer() {
14	    }
15	
16	    /** Default country code assumed when the supplied number carries no explicit '+'. */
17	    private static final String DEFAULT_COUNTRY_CODE = "61";
18	
19	    /**
20	     * Canonical E.164 form to store for a supplied telephone. Spaces, dashes and brackets
21	     * are stripped. A leading '+' with its country code is kept; otherwise country code
22	     * '+61' is assumed and a single leading '0' is dropped from the national digits. The
23	     * result must have 8 to 15 digits after the '+', else the request is rejected with a
24	     * 400. So '0412 345 678' becomes '+61412345678'.
25	     */
26	    static String normalize(String telephone) throws InvalidTelephoneException {
27	        String e164 = toE164(telephone);
28	        if (e164 == null) {
29	            throw new InvalidTelephoneException(telephone);
30	        }
31	        return e164;
32	    }
33	
34	    /**
35	     * Comparison key used to detect duplicate telephones — the E.164 form. Lenient (never
36	     * throws) so whatever is already stored on existing owners still compares; when a value
37	     * cannot form valid E.164 it falls back to its stripped characters.
38	     */
39	    static String comparisonKey(String telephone) {
40	        String e164 = toE164(telephone);
41	        return e164 != null ? e164 : stripSeparators(telephone);
42	    }
43	
44	    /**
45	     * Produce the E.164 string for a telephone, or {@code null} when it cannot form a valid
46	     * one (non-digit content remaining, or not 8 to 15 digits after the '+').
47	     */
48	    private static String toE164(String telephone) {
49	        String cleaned = stripSeparators(telephone);
50	        String digits;
51	        if (cleaned.startsWith("+")) {
52	            digits = cleaned.substring(1);
53	        }
54	        else {
55	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
56	            digits = DEFAULT_COUNTRY_CODE + national;
57	        }
58	        if (!digits.matches("\\d{8,15}")) {
59	            return null;
60	        }
61	        return "+" + digits;
62	    }
63	
64	    private static String stripSeparators(String telephone) {
65	        return telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
66	    }
67	}
